const title = root.querySelector('#t0');
const stars = root.querySelector('#st');
const cross = root.querySelector('#cr');
const cards = [root.querySelector('#c0'), root.querySelector('#c1'), root.querySelector('#c2')];
const paths = [root.querySelector('#l0'), root.querySelector('#l1')];
const crossLen = cross.getTotalLength();
cross.style.strokeDasharray = crossLen;
cross.style.strokeDashoffset = crossLen;

function frame(t, p, d) {
  const pe = clamp(p / 0.55);

  // Header and Card 1 (Messy Mermaid)
  const s1 = spr(pe, 0.0, 0.85, 14);
  title.style.opacity = E_OUT(clamp(pe * 6));
  title.style.transform = `translateY(${lerp(15, 0, E_OUT(clamp(pe * 6)))}px)`;
  cards[0].style.opacity = s1;
  cards[0].style.transform = `translateY(${lerp(30, 0, s1)}px) scale(${lerp(0.96, 1, s1)})`;

  // Strike-through (Thin red line for legibility)
  const cr_p = E_OUT(clamp((pe - 0.15) * 5));
  cross.style.opacity = cr_p * 0.8;
  cross.style.strokeDashoffset = lerp(crossLen, 0, cr_p);

  // First arrow
  const l0_p = E_OUT(clamp((pe - 0.25) * 6));
  paths[0].style.strokeDasharray = `100`;
  paths[0].style.strokeDashoffset = lerp(100, 0, l0_p);

  // Card 2 (HTML + SVG)
  const s2 = spr(pe, 0.35, 0.85, 14);
  cards[1].style.opacity = s2;
  cards[1].style.transform = `translateY(${lerp(30, 0, s2)}px) scale(${lerp(0.96, 1, s2)})`;

  // Second arrow
  const l1_p = E_OUT(clamp((pe - 0.55) * 6));
  paths[1].style.strokeDasharray = `100`;
  paths[1].style.strokeDashoffset = lerp(100, 0, l1_p);

  // Card 3 (50+ Types)
  const s3 = spr(pe, 0.65, 0.85, 14);
  cards[2].style.opacity = s3;
  cards[2].style.transform = `translateY(${lerp(30, 0, s3)}px) scale(${lerp(0.96, 1, s3)})`;

  // Footer stars
  const sf = E_OUT(clamp((pe - 0.8) * 5));
  stars.style.opacity = sf;
  stars.style.transform = `translateY(${lerp(20, 0, sf)}px)`;
}
